/* @autogenerated */
package net.civeira.phylax.feature.observe.sourcemap;

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

/**
 * A source map (revision 3) decoded to look up original positions: the mappings are decoded once
 * (base64 VLQ) into segments per generated line.
 */
public final class SourceMap {

  private static final ObjectMapper JSON = new ObjectMapper();
  private static final String BASE64 =
      "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

  /** Original position of a generated one (1-based line and column, as in the stacks). */
  public record Position(String source, int line, int column, String name) {}

  private final List<String> sources;
  private final List<String> names;
  /** Per generated line: segments {generatedColumn, source, line, column, name or -1}. */
  private final List<int[][]> lines;

  private SourceMap(final List<String> sources, final List<String> names,
      final List<int[][]> lines) {
    this.sources = sources;
    this.names = names;
    this.lines = lines;
  }

  public static SourceMap parse(final String json) throws java.io.IOException {
    JsonNode root = JSON.readTree(json);
    String sourceRoot = root.path("sourceRoot").asText("");
    List<String> sources = new ArrayList<>();
    root.path("sources").forEach(source -> sources.add(sourceRoot + source.asText()));
    List<String> names = new ArrayList<>();
    root.path("names").forEach(name -> names.add(name.asText()));
    return new SourceMap(sources, names, decode(root.path("mappings").asText("")));
  }

  /** The original position of {@code line:column} (1-based), if it is mapped. */
  public Optional<Position> lookup(final int line, final int column) {
    if (line < 1 || line > lines.size()) {
      return Optional.empty();
    }
    int[] found = null;
    for (int[] segment : lines.get(line - 1)) {
      if (segment.length >= 4 && segment[0] <= column - 1) {
        found = segment;
      } else if (segment[0] > column - 1) {
        break;
      }
    }
    if (null == found || found[1] < 0 || found[1] >= sources.size()) {
      return Optional.empty();
    }
    String name =
        found.length > 4 && found[4] >= 0 && found[4] < names.size() ? names.get(found[4]) : null;
    return Optional.of(new Position(sources.get(found[1]), found[2] + 1, found[3] + 1, name));
  }

  static List<int[][]> decode(final String mappings) {
    List<int[][]> result = new ArrayList<>();
    int source = 0;
    int originalLine = 0;
    int originalColumn = 0;
    int name = 0;
    for (String line : mappings.split(";", -1)) {
      List<int[]> segments = new ArrayList<>();
      int column = 0;
      if (!line.isEmpty()) {
        for (String segment : line.split(",")) {
          int[] values = vlq(segment);
          if (values.length == 0) {
            continue;
          }
          column += values[0];
          if (values.length >= 4) {
            source += values[1];
            originalLine += values[2];
            originalColumn += values[3];
            int nameIndex = -1;
            if (values.length >= 5) {
              name += values[4];
              nameIndex = name;
            }
            segments.add(new int[] {column, source, originalLine, originalColumn, nameIndex});
          } else {
            segments.add(new int[] {column});
          }
        }
      }
      result.add(segments.toArray(new int[0][]));
    }
    return result;
  }

  static int[] vlq(final String segment) {
    List<Integer> values = new ArrayList<>();
    int value = 0;
    int shift = 0;
    for (char c : segment.toCharArray()) {
      int digit = BASE64.indexOf(c);
      if (digit < 0) {
        return new int[0];
      }
      value += (digit & 31) << shift;
      if ((digit & 32) != 0) {
        shift += 5;
      } else {
        boolean negative = (value & 1) == 1;
        value >>= 1;
        values.add(negative ? -value : value);
        value = 0;
        shift = 0;
      }
    }
    return values.stream().mapToInt(Integer::intValue).toArray();
  }
}
